import React, { useEffect, useState } from 'react'
import { fetchPokemons } from '../data/pokemonData' // Import fetchPokemons function

function RandomPokemonImage() {
  const DAILY_KEY = 'dailyPokemon'
  const [imagePath, setImagePath] = useState('')

  useEffect(() => {
    const storedData = JSON.parse(localStorage.getItem(DAILY_KEY))

    if (storedData && isToday(storedData.date)) {
      setImagePath(storedData.imagePath)
    } else {
      fetchRandomPokemon()
    }
  }, [])

  return (
    <div className='p-8'>
      {imagePath && (
        <div className='mx-auto w-40 h-40'>
          <img
            src={imagePath}
            alt='Random Pokémon'
            className='mx-auto w-40 h-40 object-cover mb-4'
          />
        </div>
      )}
    </div>
  )
}

export default RandomPokemonImage
